import React, { useState, useEffect } from 'react';

const chordRoots = [
    'A', 'Bb', 'B', 'C', 'Db', 'D', 'Eb', 'E', 'F', 'Gb', 'G', 'Ab'
];
const chordTypes = ['Major', 'Minor'];
const defaultBpm = 0;

const chords = chordRoots.flatMap(root =>
    chordTypes.map(type => ({
        name: `${root} ${type}`,
    }))
);

function getChordKey(name, hand) {
    return `bpm_${name.replace(/\s+/g, '_')}_${hand}`;
}

function ChordTable() {
    const [bpmValues, setBpmValues] = useState({});

    useEffect(() => {
        // On mount, load all BPMs from localStorage
        const stored = {};
        chords.forEach(({ name }) => {
            ['left', 'right'].forEach(hand => {
                const key = getChordKey(name, hand);
                const value = localStorage.getItem(key);
                if (value) stored[key] = value;
            });
        });
        setBpmValues(stored);
    }, []);

    const handleBpmChange = (e, name, hand) => {
        const key = getChordKey(name, hand);
        const value = e.target.value;
        setBpmValues(prev => ({
            ...prev,
            [key]: value
        }));
        localStorage.setItem(key, value);
    };

    return (
        <div className="flex justify-center mt-8">
            <table className="min-w-[400px] w-full max-w-3xl bg-white shadow-2xl rounded-xl overflow-hidden border border-gray-200">
                <thead>
                    <tr>
                        <th className="bg-blue-700 text-white px-6 py-4 text-left text-lg font-bold">Chord Name</th>
                        <th className="bg-blue-700 text-white px-6 py-4 text-center text-lg font-bold">Left</th>
                        <th className="bg-blue-700 text-white px-6 py-4 text-center text-lg font-bold">Right</th>
                    </tr>
                </thead>
                <tbody>
                    {chords.map((chord, index) => {
                        const leftKey = getChordKey(chord.name, 'left');
                        const rightKey = getChordKey(chord.name, 'right');
                        const leftBpm = bpmValues[leftKey] ?? '';
                        const rightBpm = bpmValues[rightKey] ?? '';
                        const bpmDisplay =
                            leftBpm && rightBpm && leftBpm === rightBpm
                                ? leftBpm
                                : leftBpm && rightBpm
                                ? `${leftBpm} / ${rightBpm}`
                                : leftBpm || rightBpm || '';
                        return (
                            <tr
                                key={chord.name}
                                className={index % 2 === 0 ? "bg-blue-50 hover:bg-blue-100 transition" : "bg-white hover:bg-blue-50 transition"}
                            >
                                <td className="px-6 py-3 border-b border-gray-200">{chord.name}</td>
                                <td className="px-6 py-3 border-b border-gray-200 text-center">
                                    <input
                                        type="number"
                                        min="1"
                                        className="w-20 px-2 py-1 border rounded focus:outline-none focus:ring-2 focus:ring-blue-400"
                                        value={leftBpm}
                                        placeholder={localStorage.getItem(leftKey) || defaultBpm}
                                        onChange={e => handleBpmChange(e, chord.name, 'left')}
                                    />
                                </td>
                                <td className="px-6 py-3 border-b border-gray-200 text-center">
                                    <input
                                        type="number"
                                        min="1"
                                        className="w-20 px-2 py-1 border rounded focus:outline-none focus:ring-2 focus:ring-blue-400"
                                        value={rightBpm}
                                        placeholder={localStorage.getItem(rightKey) || defaultBpm}
                                        onChange={e => handleBpmChange(e, chord.name, 'right')}
                                    />
                                </td>
                            </tr>
                        );
                    })}
                </tbody>
            </table>
        </div>
    );
}

export default ChordTable;