import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";

// Major keys grouped by accidental preference for simple spelling
const SHARP_KEYS = ["C", "G", "D", "A", "E", "B", "F#", "C#"];
const FLAT_KEYS = ["F", "Bb", "Eb", "Ab", "Db", "Gb"];

const CHROMATIC_SHARPS = [
  "C",
  "C#",
  "D",
  "D#",
  "E",
  "F",
  "F#",
  "G",
  "G#",
  "A",
  "A#",
  "B",
];

const CHROMATIC_FLATS = [
  "C",
  "Db",
  "D",
  "Eb",
  "E",
  "F",
  "Gb",
  "G",
  "Ab",
  "A",
  "Bb",
  "B",
];

const MAJOR_STEPS = [2, 2, 1, 2, 2, 2, 1]; // Whole/whole/half...

const DEGREE_ROMANS = ["I", "ii", "iii", "IV", "V", "vi", "vii°"];
const DEGREE_QUALITIES = ["M", "m", "m", "M", "M", "m", "dim"];

function pick(arr) {
  return arr[Math.floor(Math.random() * arr.length)];
}

function buildMajorScale(root, useFlats) {
  const chromatic = useFlats ? CHROMATIC_FLATS : CHROMATIC_SHARPS;
  const start = chromatic.indexOf(root);
  if (start === -1) return [];
  const notes = [root];
  let i = start;
  for (const step of MAJOR_STEPS) {
    i = (i + step) % chromatic.length;
    notes.push(chromatic[i]);
  }
  // notes has 8 entries with octave; drop last to keep 7 distinct degrees
  return notes.slice(0, 7);
}

function chordsForKey(key) {
  const useFlats = FLAT_KEYS.includes(key);
  const scale = buildMajorScale(key, useFlats);
  // Fallback to key-only chord names if scale couldn't be built
  if (scale.length !== 7) {
    return DEGREE_ROMANS.map((roman, i) => ({
      roman,
      name: `${key} ${DEGREE_QUALITIES[i] === "m" ? "m" : DEGREE_QUALITIES[i] === "dim" ? "dim" : ""}`.trim(),
    }));
  }
  return scale.map((note, i) => ({
    roman: DEGREE_ROMANS[i],
    name:
      DEGREE_QUALITIES[i] === "M"
        ? `${note} Maj`
        : DEGREE_QUALITIES[i] === "m"
        ? `${note} min`
        : `${note} dim`,
  }));
}

export default function Progressions() {
  const [currentKey, setCurrentKey] = useState("");
  const [progression, setProgression] = useState([]); // array of { roman, name }
  const [lastUpdated, setLastUpdated] = useState(Date.now());
  // one-shot timer for next refresh and a lightweight UI tick for the progress bar
  const nextTimeoutRef = useRef(null);
  const uiIntervalRef = useRef(null);
  const [, setUiTick] = useState(0); // forces re-render for smooth bar

  const allKeys = useMemo(() => [...SHARP_KEYS, ...FLAT_KEYS], []);

  const doRandomize = useCallback(() => {
    const key = pick(allKeys);
    const diatonic = chordsForKey(key);
    // pick 4 chords (allow repeats for realistic randomness)
    const chosen = new Array(4).fill(null).map(() => pick(diatonic));
    setCurrentKey(key);
    setProgression(chosen);
    setLastUpdated(Date.now());
  }, [allKeys]);

  const scheduleNext = useCallback(() => {
    if (nextTimeoutRef.current) clearTimeout(nextTimeoutRef.current);
    nextTimeoutRef.current = setTimeout(() => {
      doRandomize();
      scheduleNext();
    }, 60_000);
  }, [doRandomize]);

  useEffect(() => {
    // initial selection and schedule
    doRandomize();
    scheduleNext();
    // lightweight UI interval to animate the progress bar
    uiIntervalRef.current = setInterval(() => setUiTick((t) => (t + 1) % 1_000_000), 200);
    return () => {
      if (nextTimeoutRef.current) clearTimeout(nextTimeoutRef.current);
      if (uiIntervalRef.current) clearInterval(uiIntervalRef.current);
    };
  }, [doRandomize, scheduleNext]);

  const handleNewNow = useCallback(() => {
    doRandomize();
    scheduleNext();
  }, [doRandomize, scheduleNext]);

  const totalMs = 60_000;
  const elapsedMs = Math.max(0, Date.now() - lastUpdated);
  const clampedElapsed = Math.min(totalMs, elapsedMs);
  const percent = Math.round((clampedElapsed / totalMs) * 100);
  const remainingSec = Math.max(0, Math.ceil((totalMs - clampedElapsed) / 1000));
  // key to restart CSS animation whenever lastUpdated changes
  const barKey = `bar-${lastUpdated}`;

  return (
    <div className="max-w-3xl mx-auto">
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-2xl font-bold">Chord Progression Trainer</h2>
        <div className="flex items-center space-x-2">
          <button
            className="px-3 py-1 rounded bg-blue-600 text-white hover:bg-blue-700"
            onClick={handleNewNow}
          >
            New now
          </button>
          <span className="text-xs text-gray-500">
            Auto-refreshes every minute
          </span>
        </div>
      </div>

      <div className="bg-white rounded shadow p-4">
        {/* Timer bar */}
        <div className="mb-3">
          <div className="flex items-center justify-between text-xs text-gray-600 mb-1">
            <span>Next in</span>
            <span>{remainingSec}s</span>
          </div>
          <div className="progress-bar-container" aria-label="Countdown to next progression" role="progressbar" aria-valuemin={0} aria-valuemax={100} aria-valuenow={percent}>
            <div key={barKey} className="progress-bar-fill" />
          </div>
        </div>

        <div className="mb-2 text-gray-600">Key</div>
        <div className="text-3xl font-semibold mb-4">{currentKey} Major</div>

        <div className="mb-2 text-gray-600">Progression (roman numerals)</div>
        <div className="text-xl font-mono mb-4">
          {progression.map((c, idx) => (
            <span key={idx}>
              {c.roman}
              {idx < progression.length - 1 ? "  –  " : ""}
            </span>
          ))}
        </div>

        <div className="mt-4 text-xs text-gray-500">
          Updated {new Date(lastUpdated).toLocaleTimeString()}
        </div>
      </div>
    </div>
  );
}
