import React, { useEffect, useRef } from "react";
import { Renderer, Stave, StaveNote, Formatter, Voice, Barline } from "vexflow";

// Chords in C major scale (triads, root position)
const CHORDS = [
    { treble: ["c/4", "e/4", "g/4"], bass: ["c/3"] }, // C
    { treble: ["d/4", "f/4", "a/4"], bass: ["d/3"] }, // Dm
    { treble: ["e/4", "g/4", "b/4"], bass: ["e/3"] }, // Em
    { treble: ["f/4", "a/4", "c/5"], bass: ["f/3"] }, // F
    { treble: ["g/4", "b/4", "d/5"], bass: ["g/3"] }, // G
    { treble: ["a/4", "c/5", "e/5"], bass: ["a/3"] }, // Am
    { treble: ["b/4", "d/5", "f/5"], bass: ["b/3"] }, // Bdim
];

function getRandomChord() {
    return CHORDS[Math.floor(Math.random() * CHORDS.length)];
}

export default function SightReading() {
    const containerRef = useRef(null);

    useEffect(() => {
        if (containerRef.current) {
            containerRef.current.innerHTML = "";
        }

        // Settings
        const measuresPerSystem = 4;
        const totalMeasures = 8;
        const measureWidth = 250;
        const staveHeight = 80;
        const startX = 40;
        const startY = 40;
        const staffGap = 0;
        const systems = 2;

        const svgWidth = startX + measuresPerSystem * measureWidth + 60;
        const svgHeight = startY + systems * (staveHeight * 2 + staffGap + 40);

        const renderer = new Renderer(containerRef.current, Renderer.Backends.SVG);
        renderer.resize(svgWidth, svgHeight);
        const context = renderer.getContext();

        // Generate random chords for each beat (8 measures x 4 beats = 32 chords)
        const chords = Array.from({ length: totalMeasures * 4 }, () => getRandomChord());

        // Draw two systems (4 measures each)
        for (let system = 0; system < systems; system++) {
            const yTreble = startY + system * (staveHeight * 2 + staffGap + 40);
            const yBass = yTreble + staveHeight + staffGap;

            // Draw the treble and bass staves for this system
            const trebleStave = new Stave(startX, yTreble, measuresPerSystem * measureWidth);
            // trebleStave.addClef("treble");
            // Add padding after clef for first measure
            // trebleStave.setNoteStartX(startX + 40); // <-- Add this line for padding
            if (system === systems - 1) trebleStave.setEndBarType(Barline.type.END);
            trebleStave.setContext(context).draw();

            const bassStave = new Stave(startX, yBass, measuresPerSystem * measureWidth);
            // bassStave.addClef("bass");
            // Add padding after clef for first measure
            bassStave.setNoteStartX(startX + 40); // <-- Add this line for padding
            if (system === systems - 1) bassStave.setEndBarType(Barline.type.END);
            bassStave.setContext(context).draw();

            // Draw a brace to connect the staves
            context.beginPath();
            context.moveTo(startX - 10, yTreble);
            context.bezierCurveTo(startX - 30, yTreble + 20, startX - 30, yBass + staveHeight - 20, startX - 10, yBass + staveHeight);
            context.lineWidth = 4;
            context.stroke();

            // Draw a vertical line connecting the staves (for grand staff look)
            // context.beginPath();
            // context.moveTo(startX, yTreble);
            // context.lineTo(startX, yBass + staveHeight + 1000);
            // context.lineTo(startX, -10);
            // context.lineWidth = 2;
            // context.stroke();

            // Draw measure dividing lines for both staves
            for (let m = 1; m < measuresPerSystem; m++) {
                const x = startX + m * measureWidth;
                // Treble
                context.beginPath();
                context.moveTo(x, yTreble);
                context.lineTo(x, yTreble + staveHeight);
                context.lineWidth = 1.5;
                context.stroke();
                // Bass
                context.beginPath();
                context.moveTo(x, yBass);
                context.lineTo(x, yBass + staveHeight);
                context.lineWidth = 1.5;
                context.stroke();
            }

            // For each measure in this system
            for (let m = 0; m < measuresPerSystem; m++) {
                const measureIdx = system * measuresPerSystem + m;
                // Get 4 chords for this measure
                const measureChords = chords.slice(measureIdx * 4, measureIdx * 4 + 4);

                // Create treble and bass notes for this measure (one chord per beat)
                const trebleNotes = measureChords.map(
                    chord =>
                        new StaveNote({
                            keys: chord.treble,
                            duration: "q"
                        })
                );
                const bassNotes = measureChords.map(
                    chord =>
                        new StaveNote({
                            keys: chord.bass,
                            duration: "q"
                        })
                );

                // Format and draw the measure for treble and bass
                Formatter.FormatAndDraw(
                    context,
                    new Stave(
                        startX + m * measureWidth,
                        yTreble,
                        measureWidth
                    ),
                    trebleNotes
                );
                Formatter.FormatAndDraw(
                    context,
                    new Stave(
                        startX + m * measureWidth,
                        yBass,
                        measureWidth
                    ),
                    bassNotes
                );
            }
        }
    }, []);

    return (
        <div className="flex flex-col items-center justify-center p-8">
            <h2 className="text-2xl font-bold text-blue-800 mb-4">Sight Reading: Grand Staff Random Chords</h2>
            <div ref={containerRef}></div>
            <div className="mt-4 text-gray-700">
                8 measures, 4 per system, each beat is a random triad from the C major scale (treble) and root in bass.
            </div>
        </div>
    );
}