import React, { useState, useRef, useEffect } from "react";
import * as Tone from "tone";
import { Line } from 'react-chartjs-2';
import { Chart, LineElement, PointElement, LinearScale, CategoryScale, Tooltip, Legend } from 'chart.js';
Chart.register(LineElement, PointElement, LinearScale, CategoryScale, Tooltip, Legend);

const TONICS = ["C2", "D2", "E2", "F2", "G2", "A2", "B2"];
const SCALE_DEGREES = [
    { label: "1", semitones: 0 },
    { label: "b2", semitones: 1 },
    { label: "2", semitones: 2 },
    { label: "b3", semitones: 3 },
    { label: "3", semitones: 4 },
    { label: "4", semitones: 5 },
    { label: "b5", semitones: 6 },
    { label: "5", semitones: 7 },
    { label: "b6", semitones: 8 },
    { label: "6", semitones: 9 },
    { label: "b7", semitones: 10 },
    { label: "7", semitones: 11 },
];
const NOTE_NAMES = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"];

function getNoteFromTonic(tonic, semitones) {
    const match = tonic.match(/^([A-G]#?)(\d)$/);
    if (!match) return tonic;
    const [ , note, octaveStr ] = match;
    const octave = parseInt(octaveStr, 10);
    const tonicIdx = NOTE_NAMES.indexOf(note);
    const absIdx = tonicIdx + octave * 12 + semitones;
    const newOctave = Math.floor(absIdx / 12);
    const newNoteIdx = ((absIdx % 12) + 12) % 12;
    return NOTE_NAMES[newNoteIdx] + newOctave;
}

// Helper: get midi number from note string (e.g. "C2" => 36)
function noteToMidi(note) {
    const match = note.match(/^([A-G]#?)(\d)$/);
    if (!match) return null;
    const [ , n, o ] = match;
    const idx = NOTE_NAMES.indexOf(n);
    return idx + 12 * (parseInt(o, 10) + 1);
}
// Helper: get note string from midi number
function midiToNote(midi) {
    const note = NOTE_NAMES[midi % 12];
    const octave = Math.floor(midi / 12) - 1;
    return note + octave;
}

// Piano diagram component
function PianoDiagram({ tonic, scaleDegrees, onNoteClick, highlightDegree, highlightTonic, hoveredDegree, setHoveredDegree }) {
    // Show 3 octaves centered on tonic's octave
    const tonicMidi = noteToMidi(tonic);
    const baseOctave = Math.floor(tonicMidi / 12);
    const keys = [];
    // Start one octave below tonic's octave
    const startMidi = (baseOctave - 1) * 12;
    for (let i = 0; i < 36; i++) { // 36 keys for 3 octaves (C to B, 12*3)
        keys.push(startMidi + i);
    }
    // Find which midi numbers correspond to each scale degree
    const degreeToMidi = {};
    scaleDegrees.forEach(deg =>{
        degreeToMidi[deg.label] = tonicMidi + deg.semitones;
    });

    return (
        <div className="flex flex-row items-end gap-0.5 select-none mb-4">
            {keys.map(midi => {
                const note = midiToNote(midi);
                const isSharp = note.includes("#");
                const isTonic = midi === tonicMidi;
                const isDegree = Object.values(degreeToMidi).includes(midi);
                // Find degree label for this midi
                let degreeLabel = null;
                for (const [label, m] of Object.entries(degreeToMidi)) {
                    if (m === midi) degreeLabel = label;
                }
                const isHighlightedDegree = highlightDegree && degreeLabel === highlightDegree;
                const isHighlightedTonic = highlightTonic && isTonic;
                const isHovered = hoveredDegree && degreeLabel === hoveredDegree;
                return (
                    <div
                        key={note}
                        onClick={() => onNoteClick && degreeLabel && onNoteClick(degreeLabel)}
                        onMouseEnter={() => setHoveredDegree && degreeLabel && setHoveredDegree(degreeLabel)}
                        onMouseLeave={() => setHoveredDegree && setHoveredDegree(null)}
                        className={`
                            relative flex flex-col items-center justify-end
                            ${isSharp ? "z-10 -ml-3" : ""}
                            ${isHighlightedDegree ? "ring-4 ring-green-400" : ""}
                            ${isHighlightedTonic ? "ring-4 ring-blue-400" : ""}
                            ${isHovered ? "ring-4 ring-yellow-400" : ""}
                            ${degreeLabel && onNoteClick ? "cursor-pointer hover:brightness-110" : ""}
                        `}
                        style={{
                            width: isSharp ? 28 : 40,
                            height: isSharp ? 90 : 140,
                            marginLeft: isSharp ? -15 : 0,
                            marginRight: isSharp ? -15 : 0,
                            marginBottom: isSharp ? 42 : 0,
                        }}
                    >
                        <div
                            className={`
                                ${isSharp
                                    ? "bg-black text-white"
                                    : "bg-white border border-gray-400 text-gray-900"}
                                w-full h-full rounded-b
                                flex items-end justify-center
                                text-xs font-bold
                                ${isTonic ? "bg-blue-200" : ""}
                                ${isHighlightedDegree ? "bg-green-200" : ""}
                                ${isHighlightedTonic ? "bg-blue-200" : ""}
                            `}
                        >
                            {isTonic ? "T" : degreeLabel}
                        </div>
                    </div>
                );
            })}
        </div>
    );
}

const GAMES_KEY = "scale_degree_games";
const ERROR_STATS_KEY = "scale_degree_error_stats";
const DEGREE_OPTIONS_KEY = "scale_degree_options";

export default function ScaleDegreeGame() {
    // Volume state
    const [volume, setVolume] = useState(() => {
        const stored = localStorage.getItem("scale_degree_volume");
        if (stored !== null) {
            const v = parseInt(stored, 10);
            if (!isNaN(v) && v >= 0 && v <= 100) return v;
        }
        return 80;
    });

    // Save volume to localStorage when it changes
    useEffect(() => {
        localStorage.setItem("scale_degree_volume", String(volume));
    }, [volume]);

    // Persistent Tone.Volume node
    const volumeNodeRef = useRef(null);
    useEffect(() => {
        if (!volumeNodeRef.current) {
            volumeNodeRef.current = new Tone.Volume((volume - 100) * 0.6).toDestination();
        }
        volumeNodeRef.current.volume.value = (volume - 100) * 0.6;
    }, [volume]);
    useEffect(() => () => {
        if (volumeNodeRef.current) {
            volumeNodeRef.current.dispose();
            volumeNodeRef.current = null;
        }
    }, []);

    // Game state
    const [gameStarted, setGameStarted] = useState(false);
    const [questions, setQuestions] = useState([]);
    const [currentIdx, setCurrentIdx] = useState(0);
    const [score, setScore] = useState(0);
    const [showScore, setShowScore] = useState(false);
    const [feedback, setFeedback] = useState("");
    const [awaitingAnswer, setAwaitingAnswer] = useState(false);
    const [restrictedDegrees, setRestrictedDegrees] = useState(null);

    // For answer stats
    const [errorStats, setErrorStats] = useState(() => {
        const saved = localStorage.getItem(ERROR_STATS_KEY);
        return saved ? JSON.parse(saved) : {};
    });
    useEffect(() => {
        localStorage.setItem(ERROR_STATS_KEY, JSON.stringify(errorStats));
    }, [errorStats]);

    // Add a reset handler for the mistakes table
    function handleResetMistakes() {
        setErrorStats({});
        localStorage.removeItem(ERROR_STATS_KEY);
    }

    // For historical games
    const [games, setGames] = useState(() => {
        const stored = localStorage.getItem(GAMES_KEY);
        return stored ? JSON.parse(stored) : [];
    });
    useEffect(() => {
        localStorage.setItem(GAMES_KEY, JSON.stringify(games));
    }, [games]);

    // Synth ref
    const synthRef = useRef(null);

    // Degree selection state (persisted)
    const [enabledDegrees, setEnabledDegrees] = useState(() => {
        const saved = localStorage.getItem(DEGREE_OPTIONS_KEY);
        return saved ? JSON.parse(saved) : SCALE_DEGREES.map(() => true);
    });

    // Save enabledDegrees to localStorage when it changes
    useEffect(() => {
        localStorage.setItem(DEGREE_OPTIONS_KEY, JSON.stringify(enabledDegrees));
    }, [enabledDegrees]);

    // Option: use piano diagram
    const [usePiano, setUsePiano] = useState(false);

    // Add hoveredDegree state
    const [hoveredDegree, setHoveredDegree] = useState(null);

    // Start a new game
    function startGame() {
        setGameStarted(true);
        setShowScore(false);
        setScore(0);
        setFeedback("");
        setCurrentIdx(0);
        setRestrictedDegrees(null);

        const numQuestions = 30;
        const enabledDegreeObjs = SCALE_DEGREES.filter((_, i) => enabledDegrees[i]);

        // Calculate accuracy for each enabled degree
        const degreeAccuracies = enabledDegreeObjs.map(deg => {
            const stat = errorStats[deg.label] || {};
            const correct = stat.correct || 0;
            const wrong = stat.wrong || 0;
            const attempts = correct + wrong;
            // If never attempted, treat as 50% accuracy (or you can use 0%)
            const accuracy = attempts > 0 ? correct / attempts : 0.5;
            return { ...deg, accuracy };
        });

        // Assign weights: lower accuracy = higher weight
        // Weight = 1 - accuracy (so 0% accuracy = 1, 100% = 0)
        const weights = degreeAccuracies.map(d => Math.max(1 - d.accuracy, 0.2));
        // If all weights are zero (all 100% accuracy), fallback to uniform
        const totalWeight = weights.reduce((a, b) => a + b, 0);
        const normalizedWeights = totalWeight > 0
            ? weights.map(w => w / totalWeight)
            : weights.map(() => 1 / weights.length);

        // Weighted random selection helper
        function weightedRandomIndex(weights) {
            const r = Math.random();
            let acc = 0;
            for (let i = 0; i < weights.length; i++) {
                acc += normalizedWeights[i];
                if (r < acc) return i;
            }
            return weights.length - 1;
        }

        const questionsArr = [];
        let tonic = TONICS[Math.floor(Math.random() * TONICS.length)];
        for (let i = 0; i < numQuestions; i++) {
            // Change tonic every 10 questions
            if (i % 10 === 0) {
                tonic = TONICS[Math.floor(Math.random() * TONICS.length)];
            }
            // Pick degree using weighted random
            const idx = weightedRandomIndex(normalizedWeights);
            const degree = enabledDegreeObjs[idx];
            questionsArr.push({
                tonic,
                degree,
            });
        }
        setQuestions(questionsArr);
    }

    // Play the current question
    async function playQuestion(q) {
        await Tone.start();
        setFeedback("");
        setAwaitingAnswer(false);

        // Stop previous synth if exists
        if (synthRef.current) {
            synthRef.current.releaseAll();
            synthRef.current.dispose();
            synthRef.current = null;
        }

        // Create synth and connect to volume node
        const synth = new Tone.PolySynth(Tone.Synth, {
            envelope: {
            attack: 0.03,
            decay: 0.1,
            sustain: 0.2,
            release: 1.2
            }
        }).connect(volumeNodeRef.current);
        synthRef.current = synth;

        // Play tonic
        synth.triggerAttackRelease([q.tonic], 10);

        // After 1 second, play scale degree
        const randomOffset = Math.floor(Math.random() * 2) * 12
        const note = getNoteFromTonic(q.tonic, q.degree.semitones + randomOffset);
        setTimeout(() => {
            synth.triggerAttackRelease([note], 5);
            setAwaitingAnswer(true);
        }, 1000);
    }

    // Handle answer
    function handleAnswer(selectedDegree) {
        const currentQuestion = questions[currentIdx];
        const correctDegree = currentQuestion.degree.label;
        const isCorrect = selectedDegree === correctDegree;

        setErrorStats(prev => {
            // Copy previous stats
            const stats = { ...prev };

            // Ensure both degrees exist in stats
            if (!stats[correctDegree]) {
                stats[correctDegree] = { correct: 0, wrong: 0 };
            }
            if (!stats[selectedDegree]) {
                stats[selectedDegree] = { correct: 0, wrong: 0 };
            }

            if (isCorrect) {
                stats[correctDegree] = {
                    ...stats[correctDegree],
                    correct: stats[correctDegree].correct + 1
                };
            } else {
                // Increment wrong for both correct and selected answer
                stats[correctDegree] = {
                    ...stats[correctDegree],
                    wrong: stats[correctDegree].wrong + 1
                };
                stats[selectedDegree] = {
                    ...stats[selectedDegree],
                    wrong: stats[selectedDegree].wrong + 1
                };
            }
            return stats;
        });

        if (!awaitingAnswer) return;
        const q = questions[currentIdx];
        const correctLabel = q.degree.label;
        let correct = false;
        if (selectedDegree === correctLabel) {
            setScore(s => s + 1);
            setFeedback("✅ Correct!");
            correct = true;
        } else {
            setFeedback(`❌ Incorrect. Correct: ${correctLabel}`);
            // Restrict to only these two degrees for the rest of the game
            setRestrictedDegrees([correctLabel, selectedDegree]);
            // Filter remaining questions to only these degrees
            setQuestions(prevQuestions => {
                // Keep already answered questions up to currentIdx + 1
                const answered = prevQuestions.slice(0, currentIdx + 1);
                // Filter the rest
                const filtered = prevQuestions
                    .slice(currentIdx + 1)
                    .filter(q =>
                        [correctLabel, selectedDegree].includes(q.degree.label)
                    );
                return [...answered, ...filtered];
            });
        }
        setAwaitingAnswer(false);

        setTimeout(() => {
            if (currentIdx + 1 < questions.length) {
                setCurrentIdx(i => i + 1);
                setFeedback("");
                playQuestion(questions[currentIdx + 1]);
            } else {
                // Game over
                setShowScore(true);
                setGameStarted(false);
                // Record game
                setGames(games => [
                    ...games,
                    {
                        date: new Date().toLocaleString(),
                        score: correct ? score + 1 : score,
                        total: questions.length,
                    },
                ]);
            }
        }, 1200);
    }

    // Helper to get most common wrong answer for a degree
    function getMostCommonWrong(degreeLabel) {
        const stats = errorStats[degreeLabel];
        if (!stats) return null;
        let max = 0, wrong = null;
        for (const [label, count] of Object.entries(stats)) {
            if (count > max) {
                max = count;
                wrong = label;
            }
        }
        return wrong ? `${wrong} (${max}×)` : null;
    }

    // Calculate total attempts and correct answers for accuracy
    const totalAttempts = Object.values(errorStats || {}).reduce(
        (sum, stat) => sum + (stat?.wrong || 0) + (stat?.correct || 0),
        0
    );
    const totalCorrect = Object.values(errorStats || {}).reduce(
        (sum, stat) => sum + (stat?.correct || 0),
        0
    );
    const totalAccuracy =
        totalAttempts > 0 ? ((totalCorrect / totalAttempts) * 100).toFixed(1) : "—";

    // Prepare per-degree accuracy data
    const degreeAccuracy = SCALE_DEGREES.map((deg) => {
        const stat = (errorStats && errorStats[deg.label]) || {};
        const correct = stat.correct || 0;
        const wrong = stat.wrong || 0;
        const attempts = correct + wrong;
        const accuracy = attempts > 0 ? ((correct / attempts) * 100).toFixed(1) : "—";
        return {
            label: deg.label,
            correct,
            wrong,
            attempts,
            accuracy,
        };
    });

    // Prepare data for the historical games graph
    const gameLabels = games.map((g, i) => `Game ${i + 1}`);
    const gameScores = games.map(g => g.score);
    const gameTotals = games.map(g => g.total);

    const chartData = {
        labels: gameLabels,
        datasets: [
            {
                label: 'Score',
                data: gameScores,
                borderColor: 'rgb(37, 99, 235)',
                backgroundColor: 'rgba(37, 99, 235, 0.2)',
                tension: 0.2,
            },
            {
                label: 'Total Questions',
                data: gameTotals,
                borderColor: 'rgb(16, 185, 129)',
                backgroundColor: 'rgba(16, 185, 129, 0.2)',
                borderDash: [5, 5],
                tension: 0.2,
            }
        ],
    };

    const chartOptions = {
        responsive: true,
        plugins: {
            legend: { display: true },
            tooltip: { enabled: true },
        },
        scales: {
            y: { beginAtZero: true, precision: 0 },
        },
    };

    return (
        <div className="flex flex-col justify-center items-center min-h-[70vh] bg-gradient-to-b from-blue-100 to-blue-50 p-6">
            <h2 className="text-3xl font-extrabold mb-6 text-blue-900 drop-shadow-lg tracking-wide">
                🎵 Scale Degree Ear Trainer
            </h2>
            {/* Volume Slider */}
            <div className="flex items-center gap-3 mb-6">
                <label htmlFor="volume-slider" className="font-mono text-blue-700 text-lg">🔊 Volume</label>
                <input
                    id="volume-slider"
                    type="range"
                    min={0}
                    max={100}
                    value={volume}
                    onChange={e => setVolume(Number(e.target.value))}
                    className="w-48 accent-blue-500 h-2 rounded-lg"
                />
                <span className="font-mono w-10 text-right text-blue-900 text-lg">{volume}</span>
            </div>


            {/* Piano/Buttons toggle */}
            {!gameStarted && !showScore && (
                <div className="mb-4 flex items-center gap-4">
                    <label className="flex items-center gap-2 font-mono text-blue-700">
                        <input
                            type="checkbox"
                            checked={usePiano}
                            onChange={e => setUsePiano(e.target.checked)}
                            className="accent-blue-600"
                        />
                        Use Piano Diagram
                    </label>
                </div>
            )}


            {/* Degree selection before game starts */}
            {!gameStarted && !showScore && (
                <div className="mb-8 w-full max-w-xl bg-white/80 rounded-xl shadow-lg p-6 border border-blue-200">
                    <h3 className="font-bold mb-3 text-blue-700 text-lg">Select Degrees to Include</h3>
                    <div className="flex flex-wrap gap-3 mb-5">
                        {SCALE_DEGREES.map((deg, i) => (
                            <label
                                key={deg.label}
                                className={`flex items-center gap-1 px-3 py-1 rounded-full border transition
                                    ${enabledDegrees[i]
                                        ? "bg-blue-100 border-blue-400 text-blue-900 font-semibold shadow"
                                        : "bg-gray-100 border-gray-300 text-gray-400"
                                    } hover:shadow-md cursor-pointer`}
                            >
                                <input
                                    type="checkbox"
                                    checked={enabledDegrees[i]}
                                    onChange={() => {
                                        setEnabledDegrees(degrees =>
                                            degrees.map((v, idx) => idx === i ? !v : v)
                                        );
                                    }}
                                    className="accent-blue-600"
                                />
                                {deg.label}
                            </label>
                        ))}
                    </div>
                    <button
                        className="bg-gradient-to-r from-blue-500 to-blue-700 text-white px-8 py-2 rounded-lg shadow-lg hover:from-blue-600 hover:to-blue-800 transition text-lg font-bold"
                        onClick={startGame}
                    >
                        Start
                    </button>
                </div>
            )}

            {gameStarted && questions.length > 0 && (
                <div className="w-full max-w-lg flex flex-col items-center bg-white/90 rounded-xl shadow-lg p-6 border border-blue-200">
                    <div className="mb-2 text-blue-700 font-mono text-lg">
                        Question <span className="font-bold">{currentIdx + 1}</span> / {questions.length}
                    </div>
                    <button
                        className="mb-4 px-4 py-1 bg-blue-200 rounded hover:bg-blue-300 font-semibold shadow transition"
                        onClick={() => playQuestion(questions[currentIdx])}
                    >
                        🔁 Replay
                    </button>
                    {usePiano ? (
                        <PianoDiagram
                            tonic={questions[currentIdx].tonic}
                            scaleDegrees={SCALE_DEGREES.filter((_, i) => enabledDegrees[i])}
                            onNoteClick={awaitingAnswer ? handleAnswer : undefined}
                            highlightDegree={null}
                            highlightTonic={true}
                            hoveredDegree={hoveredDegree}
                            setHoveredDegree={setHoveredDegree}
                        />
                    ) : (
                        <div className="grid grid-cols-4 gap-3 mb-4">
                            {SCALE_DEGREES.map((deg, i) => (
                                enabledDegrees[i] && (
                                    <button
                                        key={deg.label}
                                        className={`rounded-lg px-3 py-2 font-bold text-lg shadow transition border
                                            ${awaitingAnswer
                                                ? "bg-blue-50 hover:bg-blue-200 border-blue-300 text-blue-900"
                                                : "bg-gray-100 border-gray-200 text-gray-400 cursor-not-allowed"
                                            }`}
                                        disabled={!awaitingAnswer}
                                        onClick={() => handleAnswer(deg.label)}
                                    >
                                        {deg.label}
                                    </button>
                                )
                            ))}
                        </div>
                    )}
                    <div className="h-8 text-xl font-bold flex items-center justify-center">
                        {feedback && (
                            <span className={feedback.startsWith("✅") ? "text-green-600" : "text-red-600"}>
                                {feedback}
                            </span>
                        )}
                    </div>
                </div>
            )}

            {/* Most Common Mistakes section */}
            <div className="my-4">
                <h2 className="font-bold mb-2">Most Common Mistakes</h2>
                <button
                    className="px-3 py-1 bg-red-500 text-white rounded mb-2"
                    onClick={handleResetMistakes}
                >
                    Reset Mistakes
                </button>
                <div className="mb-2">
                    <span className="font-semibold">Total Accuracy: </span>
                    <span>{totalAccuracy}%</span>
                </div>
                <table className="min-w-max text-sm border mt-2">
                    <thead>
                        <tr>
                            <th className="px-2 py-1 border">Degree</th>
                            <th className="px-2 py-1 border">Correct</th>
                            <th className="px-2 py-1 border">Wrong</th>
                            <th className="px-2 py-1 border">Attempts</th>
                            <th className="px-2 py-1 border">Accuracy</th>
                        </tr>
                    </thead>
                    <tbody>
                        {degreeAccuracy.map((d) => (
                            <tr key={d.label}>
                                <td className="px-2 py-1 border">{d.label}</td>
                                <td className="px-2 py-1 border">{d.correct}</td>
                                <td className="px-2 py-1 border">{d.wrong}</td>
                                <td className="px-2 py-1 border">{d.attempts}</td>
                                <td className="px-2 py-1 border">
                                    {d.accuracy !== "—" ? `${d.accuracy}%` : "—"}
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {showScore && (
                <div className="w-full max-w-lg flex flex-col items-center mt-8 bg-white/90 rounded-xl shadow-lg p-6 border border-blue-200">
                    <div className="text-3xl font-extrabold text-green-700 mb-2 drop-shadow">
                        🎉 Game Over!
                    </div>
                    <div className="text-xl mb-4">
                        Your score: <span className="font-mono font-bold">{score} / {questions.length}</span>
                    </div>
                    <button
                        className="bg-gradient-to-r from-blue-500 to-blue-700 text-white px-8 py-2 rounded-lg shadow-lg hover:from-blue-600 hover:to-blue-800 transition text-lg font-bold"
                        onClick={startGame}
                    >
                        Play Again
                    </button>
                </div>
            )}

            <div className="w-full max-w-xl mt-10 mb-8">
                <h3 className="font-bold mb-2 text-blue-700 text-lg">Historical Games</h3>
                <table className="w-full text-sm border rounded-lg overflow-hidden shadow">
                    <thead>
                        <tr className="bg-blue-100">
                            <th className="border px-2 py-1">Date</th>
                            <th className="border px-2 py-1">Score</th>
                        </tr>
                    </thead>
                    <tbody>
                        {games.length === 0 && (
                            <tr>
                                <td colSpan={2} className="text-center text-gray-400 py-2">No games played yet.</td>
                            </tr>
                        )}
                        {games.slice().reverse().map((g, i) => (
                            <tr key={i} className="even:bg-blue-50">
                                <td className="border px-2 py-1 text-center">{g.date}</td>
                                <td className="border px-2 py-1 text-center font-mono">{g.score} / {g.total}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {/* Historical game performance chart */}
            <div className="my-8">
                <h2 className="text-lg font-bold mb-2">Historical Game Performance</h2>
                <Line data={chartData} options={chartOptions} />
            </div>

        </div>
    );
}